insert into public.roles(institution_id,name,slug,description,is_system)
select null,v.name,v.slug,v.description,true from (values
('Super Admin','super-admin','Full system control'),('Admin','admin','Administrative operations'),('Teacher / Ustad','teacher','Teaching operations'),('Staff','staff','General staff operations'),
('Student','student','Student portal access'),('Parent','parent','Parent portal access'),('Accountant','accountant','Fees and finance operations'),('HR','hr','Human resources operations'),
('Warden','warden','Hostel operations'),('Librarian','librarian','Library operations'),('Storekeeper','storekeeper','Inventory operations')) v(name,slug,description)
where not exists(select 1 from public.roles r where r.institution_id is null and r.slug=v.slug);

insert into public.role_permissions(role_id,permission_id)
select r.id,p.id from public.roles r cross join public.permissions p
where r.slug='super-admin' and r.institution_id is null on conflict do nothing;